import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Grade } from '../people/api';

/** A grade of the sheet, and whether it is retired: a retired grade cannot be chosen for a new person
 *  or in an edit (people on it keep it). */
export type SheetGrade = { grade: Grade; retired: boolean };

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const gradesKey = (sheetId: string) => [...sheetKey(sheetId), 'grades'] as const;

/** The grades A, B and C in order, each with whether it is retired. */
export function listGrades(sheetId: string): Promise<SheetGrade[]> {
  return getJson<SheetGrade[]>(`${sheetBase(sheetId)}/grades`);
}

/** Retire a grade; refused (rejects) for one already retired. Resolves to the grades as they now stand. */
export function retireGrade(sheetId: string, by: string, grade: string): Promise<SheetGrade[]> {
  return postJson<SheetGrade[]>(`${sheetBase(sheetId)}/grade-retire?by=${encodeURIComponent(by)}`, { grade });
}

/** How many people a grade merge gave the other grade. */
export type GradeMerged = { merged: number };

/** Merge a grade into another: everyone on it today is given the other from the sheet's today.
 *  Refused (rejects) for the same grade twice, or for anyone but a steward. */
export function mergeGrade(sheetId: string, by: string, from: string, into: string): Promise<GradeMerged> {
  return postJson<GradeMerged>(`${sheetBase(sheetId)}/grade-merge?by=${encodeURIComponent(by)}`, { from, into });
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { Grades } from './Grades';

export const contribution = SheetBody.fill({ order: 9.1, Component: Grades });
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimsKey } from '../claims/api';
import { GRADES, peopleKey } from '../people/api';
import { gradesKey, listGrades, mergeGrade, retireGrade } from './api';

/** The sheet's grades, each shown retired or not, and a select and button to retire one. A retired
 *  grade cannot be chosen for a new person or in an edit; people already on it keep it. A steward can
 *  merge a grade into another (two selects and a button), and sees how many people it regraded. */
export function Grades({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const grades = useQuery({ queryKey: gradesKey(sheetId), queryFn: () => listGrades(sheetId) });
  const [grade, setGrade] = useState<string>(GRADES[0]);

  const retire = useMutation({
    mutationFn: (input: string) => retireGrade(sheetId, user, input),
    onSuccess: (data) => {
      queryClient.setQueryData(gradesKey(sheetId), data);
      return queryClient.invalidateQueries({ queryKey: gradesKey(sheetId) });
    },
  });

  const [mergeFrom, setMergeFrom] = useState<string>(GRADES[0]);
  const [mergeInto, setMergeInto] = useState<string>(GRADES[1]);
  const merge = useMutation({
    mutationFn: (v: { from: string; into: string }) => mergeGrade(sheetId, user, v.from, v.into),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    ]),
  });

  const submitOnce = useSubmitOnce();
  const mergeOnce = useSubmitOnce();

  return (
    <section>
      <h3>Grades</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = grade;
          submitOnce(() => {
            retire.reset();
            merge.reset();
            return retire.mutateAsync(input);
          });
        }}
      >
        <select data-testid="grade-retire-select" value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            retire.reset();
          }}>
          {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
        </select>{' '}
        <button type="submit" data-testid="grade-retire" disabled={retire.isPending}>
          Retire grade
        </button>
        {retire.isError && (
          <span data-testid="grade-error">That grade is already retired.</span>
        )}
      </form>
      <div>
        Merge{' '}
        <select data-testid="grade-merge-from" value={mergeFrom}
          onChange={(e) => {
            setMergeFrom(e.target.value);
            merge.reset();
          }}>
          {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
        </select>{' '}
        into{' '}
        <select data-testid="grade-merge-into" value={mergeInto}
          onChange={(e) => {
            setMergeInto(e.target.value);
            merge.reset();
          }}>
          {GRADES.map((g) => <option key={g} value={g}>{g}</option>)}
        </select>{' '}
        <button type="button" data-testid="grade-merge" disabled={merge.isPending}
          onClick={() => {
            const v = { from: mergeFrom, into: mergeInto };
            mergeOnce(() => {
              merge.reset();
              retire.reset();
              return merge.mutateAsync(v);
            });
          }}>
          Merge grade
        </button>
        {merge.isSuccess && (
          <>
            {' '}Regraded <span data-testid="grade-merged">{merge.data.merged}</span>
          </>
        )}
        {merge.isError && (
          <span data-testid="grade-error">The grade could not be merged: pick two different grades (stewards only).</span>
        )}
      </div>
      <table>
        <tbody>
          {(grades.data ?? []).map((g) => (
            <tr key={g.grade} data-testid={`grade-row-${g.grade}`}>
              <td>{g.grade}</td>
              <td data-testid="grade-retired">{g.retired ? 'yes' : 'no'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Claim } from '../claims/api';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade a person was given, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

/** A hold on a person: from its from-date to its to-date (null: open-ended), both included (yyyy-MM-dd). */
export type Hold = { from: string; to: string | null };

/** `grade` is the one in force on the sheet's today, of their `grades` by from-date (none first).
 *  `version` is raised by every saved edit; an edit sends the version its form loaded. Their
 *  statements: how many were taken, and the last one's due-total and date (null until the first).
 *  `retiredFrom` is the date they are retired from (null: not retired); with it set at all they
 *  are `retired`, whatever the date; `retiredReached` once the sheet's today is on or after it (their
 *  open claims not bound by a statement then count in no live total). `holds` are their holds in the order added, and `held` whether
 *  they have any: their OPEN claims dated within a hold, and not bound by a statement, count in no
 *  live total. `patronIds` are the people they name
 *  as patrons, in the order named. */
/** A past retirement: from its from-date to the day they were unretired (yyyy-MM-dd). */
export type Retirement = { from: string; to: string };

export type Snapshot = { day: string; dueTotal: string };

/** A statement still standing: its date (yyyy-MM-dd) and the due-total it recorded (or n/a). */
export type StatementLine = { date: string; dueTotal: string };

export type Person = {
  id: number; sheetId: string; name: string; grade: Grade; grades: GradeFrom[]; version: number;
  statementCount: number; statedTotal: string | null; statementDate: string | null;
  retired: boolean; retiredFrom: string | null; retiredReached: boolean;
  /** Their past retirements, oldest first: a claim dated after one's from and before its to is refused. */
  retirements: Retirement[];
  /** The SNAPSHOTs written for them, oldest first: the day being left and their due-total on it (or n/a). */
  snapshots: Snapshot[];
  /** Their statements still standing (a cancelled one is gone), oldest first: by date, then as taken. */
  statements: StatementLine[];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
