package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;

/** The person form's own rules, shared by the form and the import box. */
public final class PersonForm {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private PersonForm() {
    }

    /** The person form's rules: the request trimmed and normalised, or refused. */
    public static PersonRequest check(PersonRequest request) throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty()) {
            if (!terms.matches("\\d{1,5}")) {
                throw new InvalidPersonException("Terms must be a whole number of days: " + terms);
            }
            terms = String.valueOf(Integer.parseInt(terms));
        }
        String termsFrom = request.termsFrom() == null ? "" : request.termsFrom().trim();
        if (!termsFrom.isEmpty()) {
            try {
                LocalDate.parse(termsFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + termsFrom);
            }
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        if (contact.length() > 200) {
            throw new InvalidPersonException("A contact is at most 200 characters");
        }
        return new PersonRequest(name, grade, from.isEmpty() ? null : from, terms.isEmpty() ? null : terms,
                request.version(), contact.isEmpty() ? null : contact,
                net.officefloor.hq.app.claim.ClaimForm.tags(request.tags()), termsFrom.isEmpty() ? null : termsFrom);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;

/** The rate form's rules, applied to the rate form and to each line of a rate import. */
public final class RateForm {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** 0 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("(\\d+(\\.\\d{0,2})?|\\.\\d{1,2})");

    private RateForm() {
    }

    public static ValidRate check(RateRequest request) throws InvalidRateException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidRateException("Grade must be A, B or C");
        }
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidRateException("A percent of 0.00 or more with up to two decimals is required");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidRateException("The to-date is before the from-date");
        }
        return new ValidRate(grade, new BigDecimal(pct).setScale(2), from, to);
    }

    /** A blank date is null. */
    private static LocalDate date(String given) throws InvalidRateException {
        String text = given == null ? "" : given.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("Not a date: " + text);
        }
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestParam;

/** A preview needs a grade A, B or C and a candidate percent of 0.00 or more with up to two decimals. */
public class ValidateRatePreview {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** 0 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("(\\d+(\\.\\d{0,2})?|\\.\\d{1,2})");

    public void validate(@RequestParam(name = "grade", required = false) String grade,
            @RequestParam(name = "pct", required = false) String pct, Out<ValidRate> candidate)
            throws InvalidRateException {
        String g = grade == null ? "" : grade.trim();
        String p = pct == null ? "" : pct.trim();
        if (!GRADES.contains(g)) {
            throw new InvalidRateException("Grade must be A, B or C");
        }
        if (!PCT.matcher(p).matches()) {
            throw new InvalidRateException("A percent of 0.00 or more with up to two decimals is required");
        }
        candidate.set(new ValidRate(g, new BigDecimal(p).setScale(2), null, null));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a bulk grade with no one selected, a grade not A, B or C, or a from-date not a date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeRequest> body)
            throws InvalidPersonException {
        List<Long> ids = request == null || request.personIds() == null ? List.of()
                : request.personIds().stream().filter((id) -> id != null).toList();
        if (ids.isEmpty()) {
            throw new InvalidPersonException("Select the people to grade");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
